# reconstruct test using prior variable a, seed mask
m={(0,0),(0,1),(1,0),(1,2),(1,3),(2,0)}
def transforms(m):
 out=[]
 for k in range(4):
  pts=list(m)
  for _ in range(k): pts=[(c,-r) for r,c in pts]
  for pts2 in [pts,[(r,-c) for r,c in pts]]:
   minr=min(r for r,c in pts2); minc=min(c for r,c in pts2)
   out.append({(r-minr,c-minc) for r,c in pts2})
 return out
variants=transforms(m); hits=[]
for v in variants:
 h,w=max(r for r,c in v)+1,max(c for r,c in v)+1
 for r in range(30-h+1):
  for c in range(26-w+1):
   if all(a[r+dr][c+dc]==0 for dr,dc in v):hits.append((r,c,v))
[(r,c,len(v)) for r,c,v in hits],len(hits)

b=[row[:] for row in a];
for r,c,v in hits:
 for dr,dc in v:
  if b[r+dr][c+dc]==0:b[r+dr][c+dc]=7
# print JSON
import json
print(json.dumps(b,separators=(',',':')))

comps=[{(0,0),(0,1),(1,0),(2,0)},{(0,0),(0,1)}]
out=[row[:] for row in a]
for mm in comps:
 for v in transforms(mm):
  h=max(r for r,c in v)+1;w=max(c for r,c in v)+1
  for r in range(30-h+1):
   for c in range(26-w+1):
    if all(a[r+dr][c+dc]==0 for dr,dc in v):
     for dr,dc in v: out[r+dr][c+dc]=7
print(json.dumps(out,separators=(',',':')))
